import java.text.Normalizer;
import java.util.Collections;
import java.util.List;
import java.util.Set;

public record CustomerFilter(String nameFilter, Set<CustomerStatus> statusFilter) {

    public static CustomerFilter empty() {
        return new CustomerFilter("", Collections.emptySet());
    }

    public boolean matches(Customer customer) {
        return matchesName(customer) && matchesStatus(customer);
    }

    private boolean matchesName(Customer customer) {
        if (nameFilter == null || nameFilter.isBlank()) {
            return true;
        }

        String[] terms = nameFilter.trim().split("\\s+");
        String fullName = customer.fullName();
        String firstName = customer.firstName();
        String lastName = customer.lastName();

        for (String term : terms) {
            String normalizedTerm = normalizeForMatching(term);
            String normalizedFullName = normalizeForMatching(fullName);
            String normalizedFirstName = normalizeForMatching(firstName);
            String normalizedLastName = normalizeForMatching(lastName);

            if (!normalizedFirstName.contains(normalizedTerm) &&
                !normalizedLastName.contains(normalizedTerm)) {
                return false;
            }
        }
        return true;
    }

    private boolean matchesStatus(Customer customer) {
        if (statusFilter == null || statusFilter.isEmpty()) {
            return true;
        }
        return statusFilter.contains(customer.status());
    }

    private static String normalizeForMatching(String input) {
        if (input == null) {
            return "";
        }
        String normalized = Normalizer.normalize(input, Normalizer.Form.NFD);
        return normalized.replaceAll("\\p{Mn}", "").toLowerCase();
    }
}
