+import org.junit.jupiter.api.Test;
+
+class CustomerFilterTest {
+
+    @Test
+    void emptyFilterMatchesEverything() {
+        CustomerFilter filter = CustomerFilter.empty();
+        Customer customer = new Customer(1, "John", "Doe", "john@example.com", "USA", CustomerStatus.ACTIVE);
+        assertTrue(filter.matches(customer));
+    }
+
+    @Test
+    void nameFilterWithSingleTerm() {
+        CustomerFilter filter = new CustomerFilter("john", new HashSet<>());
+        Customer john = new Customer(1, "John", "Doe", "john@example.com", "USA", CustomerStatus.ACTIVE);
+        Customer jane = new Customer(2, "Jane", "Doe", "jane@example.com", "USA", CustomerStatus.ACTIVE);
+
+        assertTrue(filter.matches(john), "Should match John");
+        assertFalse(filter.matches(jane), "Should not match Jane");
+    }
+
+    @Test
+    void nameFilterMatchesBothFirstAndLastName() {
+        CustomerFilter filter = new CustomerFilter("doe", new HashSet<>());
+        Customer customer = new Customer(1, "John", "Doe", "john@example.com", "USA", CustomerStatus.ACTIVE);
+
+        assertTrue(filter.matches(customer), "Should match last name");
+    }
+
+    @Test
+    void nameFilterWithMultipleTermsRequiresAllTerms() {
+        CustomerFilter filter = new CustomerFilter("john doe", new HashSet<>());
+        Customer john = new Customer(1, "John", "Doe", "john@example.com", "USA", CustomerStatus.ACTIVE);
+        Customer jane = new Customer(2, "Jane", "Doe", "jane@example.com", "USA", CustomerStatus.ACTIVE);
+        Customer john2 = new Customer(3, "John", "Smith", "john@example.com", "USA", CustomerStatus.ACTIVE);
+
+        assertTrue(filter.matches(john), "Should match both terms");
+        assertFalse(filter.matches(jane), "Should not match - missing 'john'");
+        assertFalse(filter.matches(john2), "Should not match - missing 'doe'");
+    }
+
+    @Test
+    void nameFilterIgnoresCaseAndAccents() {
+        CustomerFilter filter = new CustomerFilter("makinen", new HashSet<>());
+        Customer customer = new Customer(1, "Test", "Mäkinen", "test@example.com", "Finland", CustomerStatus.ACTIVE);
+
+        assertTrue(filter.matches(customer), "Should match ignoring accents");
+    }
+
+    @Test
+    void statusFilterWithEmptySelectionMatchesAll() {
+        CustomerFilter filter = new CustomerFilter("", new HashSet<>());
+        Customer active = new Customer(1, "John", "Doe", "john@example.com", "USA", CustomerStatus.ACTIVE);
+        Customer closed = new Customer(2, "Jane", "Doe", "jane@example.com", "USA", CustomerStatus.CLOSED);
+
+        assertTrue(filter.matches(active));
+        assertTrue(filter.matches(closed));
+    }
+
+    @Test
+    void statusFilterWithSelectionsOnlyMatchesSelectedStatuses() {
+        Set<CustomerStatus> statuses = new HashSet<>();
+        statuses.add(CustomerStatus.ACTIVE);
+        CustomerFilter filter = new CustomerFilter("", statuses);
+
+        Customer active = new Customer(1, "John", "Doe", "john@example.com", "USA", CustomerStatus.ACTIVE);
+        Customer closed = new Customer(2, "Jane", "Doe", "jane@example.com", "USA", CustomerStatus.CLOSED);
+        Customer pending = new Customer(3, "Bob", "Smith", "bob@example.com", "USA", CustomerStatus.PENDING);
+
+        assertTrue(filter.matches(active), "Should match ACTIVE");
