+        Customer janeActive = new Customer(3, "Jane", "Doe", "jane@example.com", "USA", CustomerStatus.ACTIVE);
+
+        assertTrue(filter.matches(johnActive), "Should match - has 'john' and ACTIVE");
+        assertFalse(filter.matches(johnClosed), "Should not match - is CLOSED");
+        assertFalse(filter.matches(janeActive), "Should not match - missing 'john'");
+    }
